from src.nodes.base import BaseNode
from src.runtime.assets import get_asset_validation_engine
from src.runtime.assets.schema import AssetDescriptor
import json

class Hou_Mcp_Asset_Validate(BaseNode):
    name = "hou_mcp_asset_validate"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("discovery_result_json", "string", widget_type="text")
        self.add_input("assets_json",           "string", widget_type="text")
        self.add_input("zone",                  "string", widget_type="text",  default="")
        self.add_input("renderer",              "string", widget_type="text",  default="")
        self.add_input("scene_scale",           "string", widget_type="text",  default="")
        self.add_output("valid_assets_json",    "string")
        self.add_output("rejected_assets_json", "string")
        self.add_output("rejection_reasons",    "string")
        self.add_output("valid_count",          "int")
        self.add_output("rejected_count",       "int")
        self.add_output("validation_ok",        "bool")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        discovery_json = inputs.get("discovery_result_json", "") or ""
        assets_json    = inputs.get("assets_json", "") or ""
        zone           = str(inputs.get("zone") or "")
        renderer       = str(inputs.get("renderer") or "")
        scene_scale    = str(inputs.get("scene_scale") or "")

        assets = []
        # Priority: wired assets_json > extract from discovery_result_json
        if assets_json.strip():
            try:
                raw = json.loads(assets_json)
                items = raw if isinstance(raw, list) else []
                assets = [AssetDescriptor.from_dict(d) for d in items if isinstance(d, dict)]
            except Exception as exc:
                self.log_error(f"Failed to parse assets_json: {exc}")
        elif discovery_json.strip():
            try:
                disc = json.loads(discovery_json)
                for qr in disc.get("query_results", []):
                    for a in qr.get("assets", []):
                        assets.append(AssetDescriptor.from_dict(a))
            except Exception as exc:
                self.log_error(f"Failed to parse discovery_result_json: {exc}")

        if not assets:
            self.log_error("No assets to validate.")
            return {"valid_assets_json": "[]", "rejected_assets_json": "[]",
                    "rejection_reasons": "{}", "valid_count": 0, "rejected_count": 0,
                    "validation_ok": False, "exec_out": True}

        try:
            report = get_asset_validation_engine().validate(
                assets, zone=zone, renderer=renderer, scene_scale=scene_scale
            )
            self.log_info(
                f"Validation: {report.valid_count} valid, {report.rejected_count} rejected"
            )
            return {
                "valid_assets_json":    json.dumps([a.to_dict() for a in report.valid_assets], default=str),
                "rejected_assets_json": json.dumps([a.to_dict() for a in report.rejected_assets], default=str),
                "rejection_reasons":    json.dumps(report.rejection_reasons),
                "valid_count":          report.valid_count,
                "rejected_count":       report.rejected_count,
                "validation_ok":        len(report.errors) == 0,
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Asset validation failed: {exc}")
            return {"valid_assets_json": "[]", "rejected_assets_json": "[]",
                    "rejection_reasons": "{}", "valid_count": 0, "rejected_count": 0,
                    "validation_ok": False, "exec_out": True}

def register_node():
    return Hou_Mcp_Asset_Validate
